<script setup>
import {ref} from 'vue';import {useOrders} from '../stores/orders.js';import {useNotifications} from '../stores/notifications.js';import {demo} from '../services/api.js';import {useRouter} from 'vue-router';import {useAuth} from '../stores/auth.js';import {useCart} from '../stores/cart.js';import {useTask} from '../composables/useTask.js';const auth=useAuth(),cart=useCart(),router=useRouter(),orders=useOrders(),notifications=useNotifications(),register=ref(false),form=ref({name:'',email:'',password:''});const {busy,error,run}=useTask();function submit(){run(async()=>{await auth.login(form.value,register.value);form.value={name:'',email:'',password:''};await router.push('/')})}function logout(){run(async()=>{await auth.logout();cart.clear();orders.clear();notifications.clear()})}
</script><template><section class="account panel"><h2>{{auth.me?'My account':register?'Create account':'Welcome back'}}</h2><p v-if="error" role="alert">{{error}}</p><template v-if="auth.me"><p>{{auth.me.user.name}} · {{auth.me.user.email}}</p><button :disabled="busy" @click="logout">Log out</button></template><form v-else @submit.prevent="submit"><p v-if="demo">Use a fictional email and demo password. This is not real authentication.</p><label v-if="register">Name<input v-model="form.name" required></label><label>Email<input v-model="form.email" type="email" autocomplete="username" required></label><label>Password<input v-model="form.password" type="password" :autocomplete="register?'new-password':'current-password'" minlength="8" required></label><button class="primary" :disabled="busy">{{register?'Register':'Log in'}}</button> <button type="button" @click="register=!register">{{register?'Back to login':'Create account'}}</button></form></section></template>
